import AVFoundation
import UIKit

/// Short app sounds (one family, generated by `Tools/sounds.py`); they mix with the music already playing and respect the silent switch.
enum SoundService {
    enum Cue: String, CaseIterable {
        case setDone = "set_done"
        case exerciseDone = "exercise_done"
        case restEnd = "rest_end"
        case sessionStart = "session_start"
        case sessionEnd = "session_end"
        case record
        case mealDone = "meal_done"
    }

    /// One prepared player per sound: no file read at the moment it must ring.
    private static var players: [Cue: AVAudioPlayer] = [:]
    /// Sets the category and activates the audio session once at launch, off the main thread: both calls can block it
    /// (iOS warns, and a sound played first would activate the session on the main thread). Ambient + mix: the music goes on.
    static func prepare() {
        Task.detached(priority: .utility) {
            let session = AVAudioSession.sharedInstance()
            try? session.setCategory(.ambient, options: [.mixWithOthers])
            try? session.setActive(true)
        }
    }

    static func play(_ cue: Cue) {
        // A timer can wake while the app is still alive in the background (location, Live Activity): the notification rings then, not the app.
        guard UIApplication.shared.applicationState == .active else { return }
        if players[cue] == nil, let url = Bundle.main.url(forResource: cue.rawValue, withExtension: "caf") {
            players[cue] = try? AVAudioPlayer(contentsOf: url)
            players[cue]?.prepareToPlay()
        }
        guard let player = players[cue] else { return }
        player.currentTime = 0
        player.play()
    }

    /// A cooking timer over while the app is open: it must be heard even with the silent switch on, so the session goes
    /// to playback for a moment (still mixed with the music), then back to ambient.
    static func timerEnded() {
        let session = AVAudioSession.sharedInstance()
        try? session.setCategory(.playback, options: [.mixWithOthers])
        try? session.setActive(true)
        play(.restEnd)
        UINotificationFeedbackGenerator().notificationOccurred(.success)
        Task {
            try? await Task.sleep(for: .seconds(4))
            try? session.setCategory(.ambient, options: [.mixWithOthers])
        }
    }

    /// Rest over while the app is open: sound + haptic (in the background the notification rings instead).
    static func restEnded() {
        play(.restEnd)
        UINotificationFeedbackGenerator().notificationOccurred(.success)
    }
}
